
use vello::{wgpu,Scene,Renderer,RendererOptions,RenderParams,AaConfig};
use vello::kurbo::{Affine,BezPath,Stroke};use vello::peniko::Color;
fn save(scene:&Scene,frame:usize,out:&std::path::Path,device:&wgpu::Device,queue:&wgpu::Queue,renderer:&mut Renderer){
 let size=wgpu::Extent3d{width:256,height:256,depth_or_array_layers:1};
 let texture=device.create_texture(&wgpu::TextureDescriptor{label:None,size,mip_level_count:1,sample_count:1,dimension:wgpu::TextureDimension::D2,format:wgpu::TextureFormat::Rgba8Unorm,usage:wgpu::TextureUsages::STORAGE_BINDING|wgpu::TextureUsages::COPY_SRC|wgpu::TextureUsages::TEXTURE_BINDING,view_formats:&[]});let view=texture.create_view(&Default::default());
 renderer.render_to_texture(device,queue,scene,&view,&RenderParams{base_color:Color::from_rgb8(9,19,31),width:256,height:256,antialiasing_method:AaConfig::Area}).unwrap();
 let buffer=device.create_buffer(&wgpu::BufferDescriptor{label:None,size:256*256*4,usage:wgpu::BufferUsages::COPY_DST|wgpu::BufferUsages::MAP_READ,mapped_at_creation:false});let mut encoder=device.create_command_encoder(&Default::default());
 encoder.copy_texture_to_buffer(wgpu::TexelCopyTextureInfo{texture:&texture,mip_level:0,origin:wgpu::Origin3d::ZERO,aspect:wgpu::TextureAspect::All},wgpu::TexelCopyBufferInfo{buffer:&buffer,layout:wgpu::TexelCopyBufferLayout{offset:0,bytes_per_row:Some(1024),rows_per_image:Some(256)}},size);queue.submit([encoder.finish()]);let slice=buffer.slice(..);let(tx,rx)=std::sync::mpsc::channel();slice.map_async(wgpu::MapMode::Read,move|r|tx.send(r).unwrap());device.poll(wgpu::PollType::wait_indefinitely()).unwrap();rx.recv().unwrap().unwrap();let pixels=slice.get_mapped_range();assert!(pixels.chunks(4).filter(|p|p[0]>40||p[1]>60||p[2]>70).count()>500);
 let mut png=png::Encoder::new(std::fs::File::create(out.join(format!("render-{frame}.png"))).unwrap(),256,256);png.set_color(png::ColorType::Rgba);png.set_depth(png::BitDepth::Eight);png.write_header().unwrap().write_image_data(&pixels).unwrap();drop(pixels);buffer.unmap();
}
fn main(){let out=std::path::PathBuf::from(std::env::args().nth(1).expect("output directory"));std::fs::create_dir_all(&out).unwrap();let mut context=vello::util::RenderContext::new();let id=pollster::block_on(context.device(None)).expect("A compute-capable wgpu adapter is required");let handle=&context.devices[id];let mut renderer=Renderer::new(&handle.device,RendererOptions::default()).unwrap();use std::str::FromStr;let animation=std::fs::read_to_string(std::env::args().nth(2).expect("animation JSON")).unwrap();let composition=velato::Composition::from_str(&animation).unwrap();let mut animator=velato::Renderer::new();for(index,frame)in [0.0,30.0,60.0].iter().enumerate(){let scene=animator.render_to_vello_scene(&composition,&std::collections::HashMap::new(),*frame,Affine::IDENTITY,1.0);save(&scene,index,&out,&handle.device,&handle.queue,&mut renderer);}let info=handle.adapter().get_info();std::fs::write(out.join("result.json"),serde_json::to_vec(&serde_json::json!({"adapter":info.name,"backend":format!("{:?}",info.backend),"width":256,"height":256})).unwrap()).unwrap();}